  & > .table-layout {

    &:hover {
      background-color: var(--listbox-hover);

      @media (prefers-contrast) {
        outline: var(--listbox-selected-outline);
        outline-offset: -2px;
      }
    }

    &.selected {
      background-color: var(--listbox-selected-bg);
    }

